"""Original ECG technical/conduction questions; chapter release review pending."""
from qbank_json_chapters import question
REFERENCES={
 'tech':('AHA/ACCF/HRS ECG Standardization, Part I','https://doi.org/10.1016/j.jacc.2007.01.024'),
 'monitor':('AHA ECG Monitoring Practice Standards, 2017','https://doi.org/10.1161/CIR.0000000000000527'),
 'udmi':('Fifth Universal Definition of Myocardial Infarction, 2026','https://doi.org/10.1016/j.jacc.2026.07.025'),
 'toxic':('AHA Special Circumstances of Resuscitation: Poisoning','https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-and-pediatric-special-circumstances-of-resuscitation/'),
 'pace':('ESC Cardiac Pacing and CRT Guideline, 2021','https://doi.org/10.1093/eurheartj/ehab364')}
rows=[]
def B(t,*c):return(t,list(c))
def Q(title,stem,answer,others,sections,table=None,refs=('tech',),calculation=False):
 r=question('ECG measurement and interpretation',title,stem,answer,others,sections,list(refs),table=table,calculation=calculation)
 r['explanationStyle']='concise_structured';rows.append(r)

Q('Paper Speed and Heart Rate','A regular rhythm is recorded at 50 mm/s. Consecutive R waves are separated by 24 small horizontal squares. What is the ventricular rate?',
 '125/min',[('62.5/min','Uses the 25 mm/s constant despite double-speed recording.'),('100/min','Would correspond to a 600 ms RR interval, not the measured interval.'),('150/min','Would require an RR interval of 400 ms, shorter than supplied.')],
 [('Calculation',[B('**At 50 mm/s, each 1 mm square is 20 ms.**','RR = 24 × 0.020 = 0.480 s; rate = 60/0.480 = **125/min**.')]),
 ('Technical Interpretation',[B('**Check speed before intervals or rhythm rate.**','The familiar 1500/small-squares rule applies at 25 mm/s; at 50 mm/s use 3000/small squares.'),B('**Gain controls voltage, not timing.**','Standard gain is 10 mm/mV; half or double gain changes apparent amplitude but not the RR interval.'),B('**Use a timed strip for irregular rhythms**, rather than treating one RR interval as the average rate.')])],calculation=True)

Q('Arm-Electrode Reversal','An asymptomatic patient has negative P, QRS and T waves in lead I, unexpectedly positive aVR and normal precordial R-wave progression. A previous ECG was normal. What should be suspected first?',
 'Right-arm/left-arm electrode reversal',[('Dextrocardia','Dextrocardia can invert lead I but usually also reverses normal precordial progression with standard left-sided chest placement; normal progression favors arm reversal.'),('Left posterior fascicular block','LPFB shifts the QRS axis but does not invert the entire P–QRS–T sequence in lead I or exchange aVR/aVL relationships.'),('Low atrial rhythm','A low atrial focus changes P-wave polarity and may shorten PR; it does not explain simultaneous reversal of ventricular depolarization and repolarization in lead I.')],
 [('Recognize the Technical Pattern',[B('**RA/LA reversal inverts lead I**, exchanges II with III and aVR with aVL; aVF is unchanged.','Precordial leads retain their usual progression because chest electrodes have not been swapped.')]),
 ('Confirm Before Labeling Disease',[B('**Check the electrode connections and repeat the ECG.**','Compare with prior tracings; do not diagnose a new axis disorder or infarction solely from the technically suspect tracing.'),B('**Dextrocardia affects chest-lead progression** as well as limb orientation; deliberate right-sided recording requires documented placement.')])])

Q('Tremor Artifact Mimicking Tachycardia','A monitor displays rapid wide oscillations, but the patient is alert with a regular palpable pulse at 78/min. Narrow QRS complexes continue at that rate through the oscillations in another lead. What is the best immediate interpretation?',
 'Movement artifact superimposed on the underlying rhythm',[('Hemodynamically tolerated sustained VT','Stable VT is possible, but persistent normal QRS complexes and a pulse matching the slower underlying rhythm strongly favor artifact here.'),('Atrial flutter with 1:1 conduction','True rapid ventricular conduction would alter the ventricular/pulse rate; the preserved slower QRS sequence contradicts a 1:1 tachycardia.'),('Pre-excited atrial fibrillation','Pre-excited AF produces an irregular rapid ventricular rhythm with variable QRS morphology, not an independent unchanged regular QRS sequence beneath noise.')],
 [('Reconcile Electrical and Clinical Data',[B('**Assess the patient and pulse immediately.**','A monitor appearance alone is insufficient; inspect multiple leads for unaffected complexes marching through noise.')]),
 ('Restore Signal Quality',[B('**Correct tremor, cable motion and poor electrode contact**, then obtain a diagnostic tracing.'),B('**Do not let apparent stability alone exclude real VT.**','The decisive evidence here is the preserved underlying electrical/pulse rhythm, not merely a conscious patient.'),B('**If perfusion is absent or unstable**, act on the emergency assessment while checking signal validity; artifact recognition must not delay needed resuscitation.')])])

Q('Refining the Frontal QRS Axis','QRS is predominantly positive in lead I, negative in aVF and positive in lead II. Which axis range best fits?',
 'Between −30° and 0°',[('Between −90° and −30°','More negative left-axis deviation would make lead II negative; its positive QRS refines this case to above −30 degrees.'),('Between +90° and +180°','Right-axis deviation produces a negative lead I with positive aVF, the opposite of the supplied limb-lead pattern.'),('Between −180° and −90°','Extreme superior axis has negative QRS in both I and aVF; lead I is positive here.')],
 [('Stepwise Axis Assessment',[B('**I positive/aVF negative** places the axis in the left-superior quadrant.','Lead II positivity narrows it to −30° to 0°, usually still within the normal adult range.')]),
 ('Clinical Limits',[B('**Axis is a vector description, not a diagnosis.**','LAFB, infarction, hypertrophy, pre-excitation and lead errors can alter it.'),B('**Check calibration and limb placement**, then integrate QRS morphology and clinical context.','An isoelectric lead can refine the estimate: the mean axis lies approximately perpendicular to that lead, with polarity resolving the direction.')])],table=(['I','aVF','Initial quadrant'],[['+','+','0° to +90°'],['+','−','−90° to 0°; inspect II'],['−','+','+90° to +180°'],['−','−','Extreme superior axis']]))

Q('Left Anterior Fascicular Block','A tracing shows QRS 104 ms, axis −60°, qR complexes in I/aVL and rS complexes in II/III/aVF. Which conduction abnormality best fits?',
 'Left anterior fascicular block',[('Complete left bundle-branch block','Complete LBBB requires a wider QRS with characteristic broad lateral R waves and loss of normal lateral septal q waves; the supplied narrow qR pattern favors LAFB.'),('Left posterior fascicular block','LPFB causes rightward rather than left-superior axis, with rS in I/aVL and qR inferiorly after excluding other right-axis causes.'),('Complete right bundle-branch block','RBBB needs delayed terminal rightward activation, typically rSR-prime in V1 and broad terminal S in I/V6 with QRS ≥120 ms; these are not supplied.')],
 [('Activation Sequence',[B('**Delayed anterior-superior LV activation** produces a left-superior mean axis.','Typical axis is −45° to −90°, qR in I/aVL and rS inferiorly; QRS is usually <120 ms.')]),
 ('Interpretation and Follow-up',[B('**Consider ischemic, hypertensive, degenerative or structural disease.**','An isolated fascicular pattern does not prove the underlying cause.'),B('**RBBB plus LAFB is bifascicular disease.**','Syncope, alternating bundle patterns or advanced AV block require evaluation beyond an incidental isolated LAFB finding.'),B('**Exclude lead errors and infarct-related axis shifts** when morphology or clinical history is discordant.')])],refs=('tech','pace'))

Q('Bifascicular Block With Long PR','An asymptomatic adult has RBBB, LAFB and PR 240 ms. What can be concluded from the surface ECG alone?',
 'Bifascicular block with first-degree AV delay; the PR delay is not necessarily in the remaining fascicle',[('Definite failure of all three fascicles','PR prolongation can arise in the AV node; the ECG does not prove that the remaining left posterior fascicle is diseased.'),('Complete AV block with a junctional escape','Complete AV block requires absence of conducted atrial impulses and independent rhythms; this patient has first-degree delay with maintained conduction.'),('Isolated AV nodal disease explaining every finding','AV nodal delay may explain PR prolongation but cannot itself account for the documented right bundle and left anterior fascicular patterns.')],
 [('Avoid Overlocalization',[B('**PR includes atrial, AV nodal and His–Purkinje conduction.**','A long PR does not locate the delay; the label “trifascicular block” can overstate what the surface ECG proves.')]),
 ('Assess Risk Clinically',[B('**Review symptoms, prior ECGs and reversible causes.**','Syncope or intermittent advanced block changes the evaluation; routine pacing is not established solely by this asymptomatic combination.'),B('**EPS can measure HV conduction in selected patients.**','Alternating bundle-branch block provides stronger evidence of extensive distal disease than PR prolongation alone.')])],refs=('pace',))

Q('Fridericia QT Correction','QT is 400 ms and RR is 512 ms. What is the Fridericia-corrected QT?',
 '500 ms',[('400 ms','Leaves the QT uncorrected for the relatively fast heart rate.'),('559 ms','Approximately the Bazett result, using the square root rather than cube root of RR.'),('781 ms','Divides by RR directly rather than its cube root.')],
 [('Calculation',[B('**QTcF = QT / cube root(RR), with intervals in seconds.**','QT = 0.400 s; RR = 0.512 s; cube root(0.512) = 0.800. QTcF = 0.400/0.800 = **0.500 s = 500 ms**.')]),
 ('Interpretation',[B('**Bazett uses square root(RR)** and often overcorrects in tachycardia.','Here QTcB is approximately 559 ms; the formula difference is clinically relevant.'),B('**QTc around 500 ms warrants review** of drugs, electrolytes, symptoms and clinical risk.','It does not alone prove congenital long QT syndrome; verify T-wave end and exclude a separate U wave.')])],refs=('monitor',),calculation=True)

Q('QT Assessment With a Wide QRS','A patient with chronic LBBB has QRS 168 ms and an automated QTc of 525 ms. Which approach best evaluates whether repolarization itself is excessively prolonged?',
 'Manual assessment using a QRS-adjusted QT or JT-based approach',[('Diagnose congenital long QT syndrome from the automated QTc alone','The QT includes delayed depolarization; wide QRS can inflate QT without equivalent repolarization prolongation, so syndrome diagnosis needs more evidence.'),('Treat the uncorrected QT as independent of heart rate','QT remains rate-dependent despite bundle-branch block; omitting rate assessment introduces a separate measurement error.'),('Exclude all arrhythmic risk because LBBB explains any QT prolongation','LBBB confounds measurement but does not prevent concurrent drug/electrolyte-related repolarization delay or ventricular arrhythmia risk.')],
 [('Separate Depolarization and Repolarization',[B('**QT = QRS duration + JT interval.**','A wide QRS lengthens QT through activation delay, so unadjusted QTc can exaggerate repolarization abnormality.')]),
 ('Practical Assessment',[B('**Measure manually and apply a validated adjustment**, with rate correction appropriate to the method.','Different formulas have limitations; use a consistent approach and seek electrophysiology input for difficult cases.'),B('**Review the clinical substrate**, drugs, electrolytes and prior tracings.','No single adjusted cutoff substitutes for symptoms, documented arrhythmias or a family history of sudden death.')])],refs=('monitor','pace'))

Q('Left Atrial Abnormality Versus Interatrial Delay','A P wave is 136 ms wide with notching in lead II and a terminal negative component in V1 that is 1.2 mm deep and 48 ms wide. Which interpretation is most defensible?',
 'Left atrial electrical abnormality; imaging is needed to establish anatomical enlargement',[('Definite mitral stenosis','This P-wave pattern can accompany many left-atrial loading conditions and interatrial delay; it does not identify a specific valve lesion.'),('Isolated right atrial enlargement','RA abnormality primarily increases early/positive P forces, often with inferior height >2.5 mm; the prolonged terminal negative component favors left-atrial involvement.'),('Normal P waves because duration remains below 200 ms','The 200 ms threshold applies to PR, not P duration; a P wave ≥120 ms is prolonged.')],
 [('Electrical Criteria',[B('**Broad/notched P in II and excessive terminal negative P force in V1** support left atrial abnormality.','A terminal negative component ≥1 mm deep and ≥40 ms wide is a useful conventional criterion.')]),
 ('Anatomy Is Not Guaranteed',[B('**Conduction delay can broaden P without major chamber enlargement.**','Advanced interatrial block typically has P ≥120 ms with positive–negative inferior P waves.'),B('**Echo quantifies atrial size and valve disease.**','Hypertension, mitral disease, diastolic dysfunction and cardiomyopathy can contribute; the historical term P mitrale is not specific for mitral stenosis.')])])

Q('Voltage Criteria and Athletic Remodeling','An asymptomatic endurance athlete has S(V1)+R(V5) of 38 mm, normal repolarization and no pathological Q waves or family history. What is the best interpretation of the voltage finding alone?',
 'It meets a conventional LVH voltage criterion but does not prove pathological hypertrophy',[('It establishes hypertrophic cardiomyopathy','Isolated high voltage is common in trained or thin individuals; HCM requires structural/clinical evidence rather than a voltage sum alone.'),('It is uninterpretable because athletes cannot meet ECG LVH criteria','The voltage can be measured and reported; the limitation is specificity for disease, not whether the criterion can be calculated.'),('It establishes hypertensive LVH despite normal blood pressure','Hypertension is one cause of LVH, but ECG voltage cannot infer an unrecorded pressure history or establish anatomical mass by itself.')],
 [('Voltage Thresholds',[B('**Sokolow–Lyon:** S(V1)+larger R(V5/V6) ≥35 mm.','Cornell voltage: R(aVL)+S(V3) >28 mm in men or >20 mm in women; recording gain must be standard.')]),
 ('Recognize Limits',[B('**Sensitivity and specificity depend on body habitus and training.**','Obesity/COPD can mask voltage; young thin athletes can have high voltage without disease.'),B('**Repolarization abnormalities, symptoms or family history change the concern.**','Lateral strain, marked T inversion or other abnormal findings warrant directed assessment; echocardiography/CMR establishes anatomy when indicated.')])])

Q('Tall R Wave in V1','A patient with chronic pulmonary hypertension has right axis deviation, R/S >1 in V1, deep S waves in V5–V6 and right-precordial T inversion. There is no acute chest pain or dynamic ST change. Which explanation best fits?',
 'Right ventricular hypertrophy with strain',[('Isolated posterior myocardial infarction','Posterior infarction can produce tall anterior R waves but typically needs compatible ischemic context and reciprocal ST changes; the rightward forces and strain pattern support RVH here.'),('Isolated left anterior fascicular block','LAFB shifts the axis superior-leftward; it does not account for right axis, dominant anterior RV forces and lateral S waves.'),('Typical complete LBBB','LBBB usually produces a predominantly negative V1 complex with broad lateral R waves; that activation pattern is opposite to the supplied dominant rightward forces.')],
 [('Integrate the Pattern',[B('**RVH:** right axis, dominant R in V1 and persistent lateral S waves.','RA abnormality and anterior ST–T strain strengthen the interpretation in pulmonary hypertension.')]),
 ('Tall R Differential',[B('**Posterior infarction, RBBB, pre-excitation and lead errors** can also produce a tall R in V1.'),B('**One voltage finding is insufficient.**','Check QRS width, delta wave, terminal R-prime, chest-lead placement and symptoms.'),B('**Echo confirms RV structure and function**; ECG cannot quantify pulmonary pressure or exclude PE by itself.')])])

Q('Pathological Q Waves in the 2026 Universal Definition','According to the Fifth Universal Definition of MI (2026), which statement describes the classical pathological Q-wave criterion?',
 'Duration ≥40 ms and/or depth ≥25% of the R wave, assessed in contiguous leads',[('Depth ≥2 mm alone in any single lead','An isolated absolute depth threshold does not represent the stated classical criterion and can misclassify normal or noninfarct Q waves.'),('Duration ≥20 ms in any limb lead regardless of depth','This lower duration threshold without distribution/context is not the classical definition adopted in the cited 2026 document.'),('Any Q wave in a lateral lead','Small lateral septal q waves can be physiological; their presence alone does not establish infarction.')],
 [('Current Definition',[B('**2026 classical criterion:** Q duration ≥40 ms and/or depth ≥25% of the same-lead R wave.','Assess two contiguous leads and the full clinical/imaging context; isolated findings require caution.')]),
 ('Do Not Equate Every Q Wave With Infarction',[B('**HCM, pre-excitation, conduction abnormalities and lead misplacement** can produce noninfarct Q waves.'),B('**A prior MI diagnosis needs compatible evidence.**','CMR/echo scar or regional dysfunction can clarify; absence of Q waves does not exclude a previous infarct.'),B('**Late acute-occlusion presentations may show Q waves/T inversion** rather than persistent ST elevation; ongoing symptoms still require urgent assessment.')])],refs=('udmi',))

Q('Hypokalemia and Apparent QT Prolongation','After prolonged vomiting, a patient has flat T waves, ST depression and large U waves in V2–V4. The machine reports QTc 610 ms, but T and U are partly fused. What is the best interpretation?',
 'Hypokalemic repolarization abnormality with possible QU mismeasurement',[('Definite congenital long QT syndrome based on the machine value','Acquired electrolyte depletion and unclear T-wave end must be addressed before diagnosing an inherited syndrome from an automated number.'),('Hypercalcemia shortening the ST segment','Hypercalcemia generally shortens QT through ST shortening; flat T waves and prominent U waves after vomiting favor potassium depletion.'),('Therapeutic digoxin effect as the complete explanation','Digoxin may cause scooped ST depression and shorter QT, but the supplied GI-loss context and prominent U waves require electrolyte assessment.')],
 [('Measurement',[B('**Exclude a separate U wave from QT.**','When T–U fusion obscures the endpoint, use a clearer lead and manual assessment; the machine may have measured QU.')]),
 ('Clinical Response',[B('**Check potassium, magnesium and renal function**, replace deficits and review QT-prolonging drugs.','Hypomagnesemia can cause refractory potassium depletion and increase ventricular arrhythmia risk.'),B('**Do not dismiss the tracing as merely a measurement error.**','Hypokalemia itself promotes ectopy and torsades; monitor severe abnormalities and reassess the ECG after correction.')])],refs=('monitor',))

Q('Calcium and the ST Segment','A patient has a markedly abbreviated ST segment and short QT, with otherwise relatively preserved T-wave morphology. Which biochemical abnormality most directly explains this pattern?',
 'Hypercalcemia',[('Hypocalcemia','Low calcium prolongs the plateau/ST segment and QT, producing the opposite direction of change.'),('Hypokalemia','Potassium depletion typically produces flat T waves, ST depression and prominent U waves rather than isolated ST shortening.'),('Hypomagnesemia','Magnesium depletion promotes arrhythmias and often accompanies QT-related risk; a very short ST segment points more directly to increased calcium.')],
 [('Repolarization Mechanism',[B('**High calcium shortens the ventricular plateau**, abbreviating ST and QT.','Low calcium prolongs ST; the effect need not require a major change in T-wave duration.')]),
 ('Confirm and Distinguish',[B('**Measure calcium and assess the clinical cause.**','Albumin and ionized calcium may matter; ECG cannot quantify the biochemical level.'),B('**Short QT also occurs with digoxin or rare inherited disease.**','Exclude acquired causes before diagnosing short QT syndrome; severe hypercalcemia can also cause PR/QRS changes or bradyarrhythmia.')])])

Q('Sodium-Channel Blocker Cardiotoxicity','After amitriptyline ingestion, a patient develops hypotension, QRS 148 ms and a prominent terminal R wave in aVR. Which treatment most directly targets the conduction toxicity?',
 'Intravenous sodium bicarbonate',[('Intravenous magnesium as the sole targeted therapy','Magnesium is central in torsades with delayed repolarization; this pattern instead identifies sodium-channel conduction blockade requiring sodium/alkalinization therapy.'),('Intravenous amiodarone as the initial targeted treatment','Amiodarone is used for selected arrhythmias, but it does not reverse the toxic sodium-channel mechanism and can add hypotension or electrophysiological effects.'),('Intravenous calcium gluconate as the principal antidote','Calcium is used for hyperkalemic membrane stabilization or selected calcium-channel blocker poisoning; it is not the principal treatment for TCA conduction toxicity.')],
 [('Toxic ECG Pattern',[B('**Fast sodium-channel blockade slows phase-0 conduction**, widening QRS and shifting terminal forces toward aVR.','Seizures, acidosis and shock can worsen toxicity; do not wait for a drug level.')]),
 ('Resuscitation',[B('**IV sodium bicarbonate boluses are titrated to improved QRS width and perfusion.**','Common initial dosing is 1–2 mEq/kg; monitor sodium, potassium and blood gas to avoid excessive alkalemia/hypernatremia.'),B('**Support ventilation and circulation and treat seizures**, with poison-center/critical-care involvement.'),B('**Continuous ECG reassessment is essential.**','A transient response does not establish toxin clearance; ongoing therapy depends on recurrent conduction toxicity and hemodynamics.')])],refs=('toxic',))
